using Microsoft.Extensions.Configuration;
using GastricCancerDetection.Application.Interfaces; using GastricCancerDetection.Infrastructure.Persistence; using ClosedXML.Excel; using Microsoft.EntityFrameworkCore;
namespace GastricCancerDetection.Infrastructure.Services; public class ReportService:IReportService { private readonly GastricCancerDbContext _db; private readonly IConfiguration _cfg; public ReportService(GastricCancerDbContext db,IConfiguration cfg){_db=db;_cfg=cfg;} public async Task<string> GenerateExcelAsync(int runId,CancellationToken ct=default){var dir=_cfg["Storage:ReportsPath"]??"storage/reports";Directory.CreateDirectory(dir);var path=Path.Combine(dir,$"analysis-{runId}.xlsx");using var wb=new XLWorkbook();var summary=wb.Worksheets.Add("01_Executive_Summary");summary.Cell(1,1).Value="Analysis Run";summary.Cell(1,2).Value=runId;var cand=wb.Worksheets.Add("02_Candidate_Matrix");var cs=await _db.Candidates.AsNoTracking().Where(x=>x.AnalysisRunId==runId).OrderByDescending(x=>x.OverallPriority).ToListAsync(ct);cand.Cell(1,1).Value="Candidate";cand.Cell(1,2).Value="FeatureType";cand.Cell(1,3).Value="cfDNADetectabilityScore";cand.Cell(1,4).Value="OverallPriority";for(int i=0;i<cs.Count;i++){cand.Cell(i+2,1).Value=cs[i].CandidateKey;cand.Cell(i+2,2).Value=cs[i].FeatureType;cand.Cell(i+2,3).Value=cs[i].CfDNADetectabilityScore;cand.Cell(i+2,4).Value=cs[i].OverallPriority;}foreach(var n in new[]{"03_NonCoding_Hotspots","04_CNA","05_Mitochondrial","06_PMD_Regions","07_Repeat_Methylation","08_Liquid_Biopsy","09_cfDNA_Detectability","10_Integrated_Panels","11_Literature_Whitespace","12_Evidence","13_Score_Model","14_Search_Log","15_Sources"})wb.Worksheets.Add(n).Cell(1,1).Value="Not yet available";wb.SaveAs(path);return path;} public Task<string> GeneratePdfAsync(int runId,CancellationToken ct=default)=>throw new NotSupportedException("PDF redesign is intentionally pending until the Phase 1 data contract is populated."); }
